const checks = [
  {
    name: 'Netlify Frontend',
    url: 'https://assists.agenceattractor.com',
    method: 'GET',
    expectStatus: 200
  },
  {
    name: 'Supabase Auth',
    url: 'https://lgdgbrivnhgeupqhkckd.supabase.co/auth/v1/health',
    method: 'GET',
    expectStatus: 200
  },
  {
    name: 'Edge: chat-assistant',
    url: 'https://lgdgbrivnhgeupqhkckd.supabase.co/functions/v1/chat-assistant',
    method: 'POST',
    badStatus: 500
  },
  {
    name: 'Edge: init-payment',
    url: 'https://lgdgbrivnhgeupqhkckd.supabase.co/functions/v1/init-payment',
    method: 'POST',
    badStatus: 500
  }
];

const results = [];
for (const check of checks) {
  try {
    const res = await fetch(check.url, {
      method: check.method,
      headers: { 'Content-Type': 'application/json' },
      body: check.method === 'POST' ? '{}' : undefined,
      signal: AbortSignal.timeout(10000)
    });
    const ok = check.expectStatus
      ? res.status === check.expectStatus
      : res.status !== check.badStatus;
    results.push({ name: check.name, status: res.status, ok });
  } catch (e) {
    results.push({ name: check.name, status: 0, ok: false, error: e.message });
  }
}

const failures = results.filter(r => !r.ok);
const now = new Date().toLocaleString('fr-FR', { timeZone: 'Europe/Paris' });

const rows = failures
  .map(f => `<tr><td style="padding:8px;border:1px solid #ddd"><b>${f.name}</b></td><td style="padding:8px;border:1px solid #ddd">HTTP ${f.status}</td><td style="padding:8px;border:1px solid #ddd">${f.error || 'Statut inattendu'}</td></tr>`)
  .join('');

const emailHtml = `<h2 style="color:#cc0000">Assists — ${failures.length} panne(s) detectee(s) — ${now}</h2><table style="border-collapse:collapse;width:100%">${rows}</table><br><p><b>Verifier maintenant :</b></p><ul><li>Supabase dashboard</li><li>Netlify deploy logs</li><li>Resend logs (si c'est l'OTP)</li></ul>`;

const emailPayloadStr = JSON.stringify({
  from: 'noreply@agenceattractor.com',
  to: 'macarthur.nguessankouassi@gmail.com',
  subject: 'ALERTE Assists — ' + failures.length + ' panne(s) — ' + now,
  html: emailHtml
});

return [{ json: { results, failures, hasFailures: failures.length > 0, checkedAt: now, emailPayloadStr } }];
